INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('DEGUSTAÇÃO DE PRODUTOS LOCAIS', 'EXPERIÊNCIA DE DEGUSTAÇÃO DE ALIMENTOS, BEBIDAS E PRODUTOS ARTESANAIS PRODUZIDOS NA PROPRIEDADE OU NA REGIÃO, VALORIZANDO A PRODUÇÃO E A CULTURA LOCAL.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('RECREAÇÃO RURAL', 'CONJUNTO DE ATIVIDADES RECREATIVAS REALIZADAS EM AMBIENTES RURAIS, INCLUINDO LAZER, CONVIVÊNCIA, BRINCADEIRAS E EXPERIÊNCIAS RELACIONADAS À VIDA NO CAMPO.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('PASSEIO EM ÁREAS RURAIS', 'PASSEIOS ORIENTADOS OU LIVRES EM PROPRIEDADES E PAISAGENS RURAIS PARA CONTEMPLAÇÃO, CONHECIMENTO DA PRODUÇÃO E CONTATO COM O AMBIENTE DO CAMPO.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('FOTOGRAFIA DE NATUREZA', 'ATIVIDADE DE REGISTRO FOTOGRÁFICO DE PAISAGENS, FAUNA, FLORA E ELEMENTOS DO AMBIENTE RURAL E NATURAL.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('EVENTOS CULTURAIS RURAIS', 'REALIZAÇÃO DE EVENTOS, ENCONTROS E MANIFESTAÇÕES CULTURAIS RELACIONADAS ÀS TRADIÇÕES, COSTUMES, PRODUÇÃO E IDENTIDADE DAS COMUNIDADES RURAIS.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('PIQUENIQUE', 'ATIVIDADE DE LAZER E ALIMENTAÇÃO REALIZADA EM ÁREAS VERDES OU RURAIS PREPARADAS PARA RECEBER VISITANTES.', (SELECT ID_CATEGORIA FROM ATIVIDADES_CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('CERTIFICAÇÃO ORGÂNICA PARTICIPATIVA', 'Processo de garantia de qualidade orgânica baseado na confiança e no controle social entre os próprios agricultores e consumidores, dispensando auditorias externas caras.', 9);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('GERAÇÃO DE ENERGIA RENOVÁVEL RURAL', 'Instalação e operação de sistemas de geração de energia limpa em propriedades rurais, como painéis solares, biodigestores ou pequenas turbinas eólicas, visando autossuficiência e sustentabilidade.', 9);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('INCLUSÃO DIGITAL PARA PRODUTORES RURAIS', 'Capacitação e acesso a tecnologias da informação para agricultores, englobando o uso de aplicativos de gestão, previsão do tempo, acesso a mercados online e plataformas de ensino à distância.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('RASTREABILIDADE DE ALIMENTOS', 'Implementação de sistemas (manuais ou digitais) que permitem acompanhar o caminho do produto agrícola desde o plantio até o consumidor final, garantindo transparência, origem e segurança alimentar.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE INSUMOS AGRÍCOLAS', 'VENDA DE SEMENTES, FERTILIZANTES, DEFENSIVOS, SUBSTRATOS E OUTROS INSUMOS UTILIZADOS NA PRODUÇÃO AGRÍCOLA.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE MÁQUINAS E IMPLEMENTOS AGRÍCOLAS', 'VENDA DE TRATORES, MOTOCULTORES, IMPLEMENTOS, FERRAMENTAS MOTORIZADAS E EQUIPAMENTOS DESTINADOS À PRODUÇÃO AGRÍCOLA.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('MANUTENÇÃO DE MÁQUINAS E EQUIPAMENTOS AGRÍCOLAS', 'REALIZAÇÃO DE INSPEÇÕES, REVISÕES, REPAROS E MANUTENÇÃO PREVENTIVA E CORRETIVA DE MÁQUINAS E EQUIPAMENTOS AGRÍCOLAS.', 2);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('LOCAÇÃO DE MÁQUINAS E EQUIPAMENTOS AGRÍCOLAS', 'DISPONIBILIZAÇÃO TEMPORÁRIA DE TRATORES, ROÇADEIRAS, MOTOCULTORES, IMPLEMENTOS E OUTROS EQUIPAMENTOS UTILIZADOS NAS ATIVIDADES AGRÍCOLAS.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('ANÁLISE DE SOLO E ÁGUA', 'REALIZAÇÃO DE ANÁLISES FÍSICAS, QUÍMICAS E BIOLÓGICAS DE SOLO E ÁGUA PARA AVALIAÇÃO DA FERTILIDADE, QUALIDADE E ADEQUAÇÃO AO USO AGRÍCOLA.', 2);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('MONITORAMENTO E MAPEAMENTO AGRÍCOLA', 'UTILIZAÇÃO DE DRONES, SENSORES, GEOTECNOLOGIAS E SISTEMAS DIGITAIS PARA MONITORAMENTO DE CULTURAS, MAPEAMENTO DE ÁREAS PRODUTIVAS E APOIO À GESTÃO AGRÍCOLA.', 2);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('CONTROLE INTEGRADO DE PRAGAS AGRÍCOLAS', 'MONITORAMENTO, PREVENÇÃO E CONTROLE DE PRAGAS AGRÍCOLAS POR MEIO DE MÉTODOS BIOLÓGICOS, CULTURAIS, FÍSICOS E QUÍMICOS, CONFORME AS NECESSIDADES DO CULTIVO.', 2);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('PLANTIO PARTICIPATIVO', 'EXPERIÊNCIA PRÁTICA EM QUE OS VISITANTES PARTICIPAM DO PLANTIO DE SEMENTES E MUDAS, PREPARAÇÃO DE CANTEIROS E APRENDIZADO SOBRE TÉCNICAS DE CULTIVO AGRÍCOLA.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COLHEITA PARTICIPATIVA', 'EXPERIÊNCIA EM QUE OS VISITANTES PARTICIPAM DIRETAMENTE DA COLHEITA DE HORTALIÇAS, FRUTAS, ERVAS E OUTROS PRODUTOS AGRÍCOLAS, CONHECENDO AS ETAPAS DE PRODUÇÃO E OS CUIDADOS NECESSÁRIOS.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('OFICINA DE PRODUÇÃO DE MUDAS', 'ATIVIDADE EDUCATIVA E PRÁTICA SOBRE PRODUÇÃO DE MUDAS, PREPARAÇÃO DE SUBSTRATOS, GERMINAÇÃO DE SEMENTES, TRANSPLANTIO E CUIDADOS INICIAIS COM AS PLANTAS.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('VIVÊNCIA DE COMPOSTAGEM', 'EXPERIÊNCIA EDUCATIVA QUE PERMITE AOS VISITANTES CONHECER E PARTICIPAR DO PROCESSO DE TRANSFORMAÇÃO DE RESÍDUOS ORGÂNICOS EM COMPOSTO, INCENTIVANDO PRÁTICAS SUSTENTÁVEIS.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('IDENTIFICAÇÃO DE PLANTAS E ESPÉCIES NATIVAS', 'ATIVIDADE EDUCATIVA DE RECONHECIMENTO DE ESPÉCIES VEGETAIS, SUAS CARACTERÍSTICAS, UTILIDADES, IMPORTÂNCIA ECOLÓGICA E CONTRIBUIÇÃO PARA A PRESERVAÇÃO DA BIODIVERSIDADE.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('IMERSÃO NA ROTINA RURAL', 'EXPERIÊNCIA DE TURISMO RURAL QUE PROPORCIONA AOS VISITANTES O ACOMPANHAMENTO E A PARTICIPAÇÃO EM ATIVIDADES COTIDIANAS DE UMA PROPRIEDADE AGRÍCOLA, APRESENTANDO COSTUMES, TRADIÇÕES E PRÁTICAS DO CAMPO.', 10);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('ALIMENTAÇÃO DE ANIMAIS DA FAZENDA', 'EXPERIÊNCIA DE CONTATO SUPERVISIONADO COM ANIMAIS DE CRIAÇÃO, PERMITINDO AOS VISITANTES PARTICIPAR DA ALIMENTAÇÃO E CONHECER OS CUIDADOS BÁSICOS, O BEM-ESTAR E O MANEJO RESPONSÁVEL DOS ANIMAIS.', 10);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('PREPARO DE ALIMENTOS COM PRODUTOS LOCAIS', 'EXPERIÊNCIA GASTRONÔMICA PARTICIPATIVA NA QUAL OS VISITANTES APRENDEM A PREPARAR RECEITAS UTILIZANDO INGREDIENTES PRODUZIDOS LOCALMENTE, VALORIZANDO A CULTURA ALIMENTAR E OS PRODUTOS DA AGRICULTURA FAMILIAR.', 10);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE HORTIFRUTIGRANJEIROS', 'COMERCIALIZAÇÃO DE FRUTAS, VERDURAS, LEGUMES, OVOS E OUTROS PRODUTOS HORTIFRUTIGRANJEIROS, PROMOVENDO O ACESSO A ALIMENTOS FRESCOS E O FORTALECIMENTO DO COMÉRCIO LOCAL.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE PRODUTOS ORGÂNICOS', 'COMERCIALIZAÇÃO DE ALIMENTOS E PRODUTOS OBTIDOS POR SISTEMAS DE PRODUÇÃO ORGÂNICA, CONFORME OS CRITÉRIOS DE CERTIFICAÇÃO E REGULARIZAÇÃO APLICÁVEIS.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE PRODUTOS AGROECOLÓGICOS', 'COMERCIALIZAÇÃO DE ALIMENTOS E PRODUTOS PROVENIENTES DE SISTEMAS AGROECOLÓGICOS, VALORIZANDO PRÁTICAS SUSTENTÁVEIS, A AGRICULTURA FAMILIAR E A CONSERVAÇÃO AMBIENTAL.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE PRODUTOS ARTESANAIS', 'COMERCIALIZAÇÃO DE ARTESANATOS, OBJETOS DECORATIVOS, UTENSÍLIOS E OUTROS PRODUTOS DE FABRICAÇÃO ARTESANAL, VALORIZANDO A PRODUÇÃO LOCAL E AS TRADIÇÕES CULTURAIS.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE ALIMENTOS PREPARADOS', 'COMERCIALIZAÇÃO DE REFEIÇÕES, LANCHES, DOCES, SALGADOS, BEBIDAS E OUTROS ALIMENTOS PREPARADOS PARA CONSUMO IMEDIATO OU POSTERIOR.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE FLORES E PLANTAS', 'COMERCIALIZAÇÃO DE FLORES, PLANTAS ORNAMENTAIS, MUDAS, ESPÉCIES NATIVAS E OUTROS PRODUTOS VEGETAIS DESTINADOS AO PAISAGISMO, JARDINAGEM E CULTIVO DOMÉSTICO.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('COMERCIALIZAÇÃO DE PRODUTOS DA AGRICULTURA FAMILIAR', 'COMERCIALIZAÇÃO DE ALIMENTOS, PRODUTOS BENEFICIADOS E OUTRAS MERCADORIAS PRODUZIDAS POR AGRICULTORES FAMILIARES, INCENTIVANDO A GERAÇÃO DE RENDA E O DESENVOLVIMENTO RURAL.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('EXPOSIÇÃO DE PRODUTOS REGIONAIS', 'APRESENTAÇÃO E DIVULGAÇÃO DE PRODUTOS TÍPICOS DA REGIÃO, INCLUINDO ALIMENTOS, ARTESANATOS E MERCADORIAS LOCAIS, COM O OBJETIVO DE VALORIZAR A IDENTIDADE CULTURAL E A PRODUÇÃO REGIONAL.', 3);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('APRESENTAÇÕES ARTÍSTICAS E CULTURAIS', 'REALIZAÇÃO DE APRESENTAÇÕES MUSICAIS, DANÇAS, TEATRO E OUTRAS MANIFESTAÇÕES ARTÍSTICAS E CULTURAIS EM ESPAÇOS DE CONVIVÊNCIA, FEIRAS E EVENTOS COMUNITÁRIOS.', 10);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('OFICINAS DE GASTRONOMIA REGIONAL', 'REALIZAÇÃO DE OFICINAS EDUCATIVAS E PRÁTICAS SOBRE PREPARAÇÃO DE RECEITAS TÍPICAS, TÉCNICAS CULINÁRIAS TRADICIONAIS E APROVEITAMENTO DE INGREDIENTES PRODUZIDOS REGIONALMENTE.', 4);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('CAMPANHAS DE ARRECADAÇÃO DE ALIMENTOS', 'ORGANIZAÇÃO DE CAMPANHAS SOLIDÁRIAS PARA ARRECADAÇÃO DE ALIMENTOS DESTINADOS A FAMÍLIAS EM SITUAÇÃO DE VULNERABILIDADE SOCIAL, ENTIDADES ASSISTENCIAIS E INICIATIVAS DE SEGURANÇA ALIMENTAR.', 1);
INSERT INTO ATIVIDADES (ATIVIDADE, DESCRICAO, ID_CATEGORIA) VALUES ('EDUCAÇÃO ALIMENTAR E NUTRICIONAL', 'REALIZAÇÃO DE ATIVIDADES EDUCATIVAS SOBRE ALIMENTAÇÃO SAUDÁVEL, VALOR NUTRICIONAL DOS ALIMENTOS, ESCOLHAS ALIMENTARES CONSCIENTES E PREVENÇÃO DO DESPERDÍCIO.', 4);
