INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('AGRICULTURA', 'ABRANGE ESPAÇOS, UNIDADES E ESTRUTURAS DIRETAMENTE RELACIONADOS AO CULTIVO, PRODUÇÃO VEGETAL E DESENVOLVIMENTO DE PRÁTICAS AGRÍCOLAS.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('COMÉRCIO', 'ABRANGE ESTABELECIMENTOS E ESPAÇOS DESTINADOS À VENDA, EXPOSIÇÃO, DISTRIBUIÇÃO OU COMERCIALIZAÇÃO DE PRODUTOS AGRÍCOLAS, LOCAIS E RURAIS.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('EDUCAÇÃO', 'ABRANGE INSTITUIÇÕES E ESPAÇOS DESTINADOS AO ENSINO, CAPACITAÇÃO, FORMAÇÃO E DIFUSÃO DE CONHECIMENTOS RELACIONADOS À AGRICULTURA E AO MEIO AMBIENTE.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('GASTRONOMIA', 'ABRANGE ESTABELECIMENTOS E ESTRUTURAS RELACIONADOS À PREPARAÇÃO, TRANSFORMAÇÃO E OFERTA DE ALIMENTOS, ESPECIALMENTE PRODUTOS LOCAIS E RURAIS.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('INFRAESTRUTURA', 'ABRANGE INSTALAÇÕES FÍSICAS DESTINADAS AO ARMAZENAMENTO, BENEFICIAMENTO, ABASTECIMENTO, DISTRIBUIÇÃO E SUPORTE À CADEIA PRODUTIVA AGRÍCOLA.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('PESQUISA E TECNOLOGIA', 'ABRANGE UNIDADES DESTINADAS À PESQUISA, EXPERIMENTAÇÃO, DEMONSTRAÇÃO E DESENVOLVIMENTO DE TÉCNICAS, TECNOLOGIAS E SOLUÇÕES APLICADAS À AGRICULTURA.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('PROPRIEDADE', 'ABRANGE DIFERENTES TIPOS DE IMÓVEIS, UNIDADES TERRITORIAIS E ESTABELECIMENTOS RURAIS OU PRODUTIVOS.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('SERVIÇOS', 'ABRANGE UNIDADES E ESTRUTURAS DESTINADAS À PRESTAÇÃO DE ASSISTÊNCIA, ORIENTAÇÃO, EXTENSÃO E SUPORTE AOS PRODUTORES E DEMAIS ENTIDADES DO SETOR.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('SUSTENTABILIDADE', 'ABRANGE ESPAÇOS E ESTRUTURAS VOLTADOS À CONSERVAÇÃO AMBIENTAL, RECUPERAÇÃO DE RECURSOS NATURAIS E PROMOÇÃO DE PRÁTICAS SUSTENTÁVEIS.');
INSERT INTO CATEGORIAS (CATEGORIA, DESCRICAO) VALUES ('TURISMO', 'ABRANGE LOCAIS, ESTABELECIMENTOS E ESTRUTURAS DESTINADOS À VISITAÇÃO, HOSPEDAGEM E VALORIZAÇÃO TURÍSTICA DOS AMBIENTES RURAIS E NATURAIS.');
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('ORG-AUD-PPV', 'CERTIFICAÇÃO ORGÂNICA POR AUDITORIA – PRODUÇÃO PRIMÁRIA VEGETAL', 'CERTIFICAÇÃO DA PRODUÇÃO PRIMÁRIA VEGETAL ORGÂNICA REALIZADA POR MEIO DE AUDITORIA, COM VERIFICAÇÃO DO ATENDIMENTO ÀS NORMAS E REQUISITOS DA PRODUÇÃO ORGÂNICA.', 1);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('ORG-SPG-PPV', 'CERTIFICAÇÃO ORGÂNICA PARTICIPATIVA – PRODUÇÃO PRIMÁRIA VEGETAL', 'CERTIFICAÇÃO DA PRODUÇÃO PRIMÁRIA VEGETAL ORGÂNICA REALIZADA POR SISTEMA PARTICIPATIVO DE GARANTIA, COM RESPONSABILIDADE E CONTROLE COMPARTILHADOS ENTRE SEUS PARTICIPANTES.', 1);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('CTA', 'CERTIFICADO DE TRANSIÇÃO AGROECOLÓGICA', 'CERTIFICAÇÃO DESTINADA A PRODUTORES EM PROCESSO DE TRANSIÇÃO PARA SISTEMAS DE PRODUÇÃO AGROECOLÓGICOS, INCENTIVANDO A REDUÇÃO DE INSUMOS CONVENCIONAIS E A ADOÇÃO DE PRÁTICAS SUSTENTÁVEIS.', 2);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('PI', 'CERTIFICAÇÃO DE PRODUÇÃO INTEGRADA AGROPECUÁRIA', 'CERTIFICAÇÃO BASEADA NA ADOÇÃO DE BOAS PRÁTICAS AGROPECUÁRIAS, RASTREABILIDADE, SEGURANÇA DOS ALIMENTOS, RESPONSABILIDADE AMBIENTAL E GESTÃO SUSTENTÁVEL DA PRODUÇÃO.', 3);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('CM-ORG', 'CERTIFICA MINAS ORGÂNICOS', 'CERTIFICAÇÃO DESTINADA À PRODUÇÃO ORGÂNICA QUE ATENDE AOS REQUISITOS E CRITÉRIOS ESTABELECIDOS PELO PROGRAMA CERTIFICA MINAS.', 4);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('CM-SAT', 'CERTIFICA MINAS SEM AGROTÓXICOS', 'CERTIFICAÇÃO DESTINADA A SISTEMAS DE PRODUÇÃO VEGETAL CONDUZIDOS SEM O USO DE AGROTÓXICOS, CONFORME OS REQUISITOS ESTABELECIDOS PELO PROGRAMA CERTIFICA MINAS.', 4);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('IFA-V6-SMART', 'INTEGRATED FARM ASSURANCE V6 SMART – PLANTS', 'CERTIFICAÇÃO INTERNACIONAL VOLTADA À PRODUÇÃO VEGETAL, COM ÊNFASE EM BOAS PRÁTICAS AGRÍCOLAS, RASTREABILIDADE, SEGURANÇA DOS ALIMENTOS, RESPONSABILIDADE AMBIENTAL E GESTÃO DA PROPRIEDADE.', 5);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('SPO', 'FAIRTRADE STANDARD FOR SMALL-SCALE PRODUCER ORGANISATIONS', 'CERTIFICAÇÃO DESTINADA A ORGANIZAÇÕES DE PEQUENOS PRODUTORES, COM REQUISITOS RELACIONADOS AO COMÉRCIO JUSTO, ORGANIZAÇÃO COLETIVA, CONDIÇÕES DE TRABALHO E SUSTENTABILIDADE.', 7);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('FFL', 'FAIR FOR LIFE CERTIFICATION', 'CERTIFICAÇÃO DE COMÉRCIO JUSTO E RESPONSABILIDADE SOCIOAMBIENTAL APLICÁVEL A PRODUTORES, ORGANIZAÇÕES E CADEIAS PRODUTIVAS.', 8);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('DEMETER', 'DEMETER BIODYNAMIC CERTIFICATION', 'CERTIFICAÇÃO DESTINADA À PRODUÇÃO AGRÍCOLA E AO PROCESSAMENTO DE PRODUTOS REALIZADOS DE ACORDO COM OS PRINCÍPIOS E PADRÕES DA AGRICULTURA BIODINÂMICA.', 9);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('SAS', 'SUSTAINABLE AGRICULTURE CERTIFICATION', 'CERTIFICAÇÃO VOLTADA À ADOÇÃO DE PRÁTICAS DE AGRICULTURA SUSTENTÁVEL, CONSIDERANDO CRITÉRIOS AMBIENTAIS, SOCIAIS, ECONÔMICOS E DE CONSERVAÇÃO DOS RECURSOS NATURAIS.', 6);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('RAS', 'REGENERATIVE AGRICULTURE CERTIFICATION', 'CERTIFICAÇÃO VOLTADA À ADOÇÃO DE PRÁTICAS AGRÍCOLAS REGENERATIVAS QUE CONTRIBUAM PARA A RECUPERAÇÃO DO SOLO, CONSERVAÇÃO DA BIODIVERSIDADE E MELHORIA DOS ECOSSISTEMAS PRODUTIVOS.', 6);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('ROC', 'REGENERATIVE ORGANIC CERTIFIED', 'CERTIFICAÇÃO QUE COMBINA REQUISITOS DE PRODUÇÃO ORGÂNICA COM PRÁTICAS REGENERATIVAS, SAÚDE DO SOLO, BEM-ESTAR ANIMAL E RESPONSABILIDADE SOCIAL.', 10);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('ORG-BR', 'ORGÂNICO BRASIL', 'CERTIFICAÇÃO DESTINADA À CONFORMIDADE DA PRODUÇÃO, PROCESSAMENTO OU COMERCIALIZAÇÃO COM OS REQUISITOS BRASILEIROS APLICÁVEIS À PRODUÇÃO ORGÂNICA.', (SELECT ID_PROGRAMA FROM CERTIFICACAO_PROGRAMAS WHERE PROGRAMA_SIGLA = 'SISORG'));
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('ORG-EXP', 'ORGÂNICO EXPORTAÇÃO', 'CERTIFICAÇÃO DESTINADA A PRODUTOS ORGÂNICOS VOLTADOS AO MERCADO INTERNACIONAL, CONSIDERANDO REQUISITOS ESPECÍFICOS DO PAÍS OU BLOCO ECONÔMICO DE DESTINO.', NULL);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('UA', 'UNIDADES ARMAZENADORAS', 'CERTIFICAÇÃO DESTINADA A ESTRUTURAS DE ARMAZENAMENTO DE PRODUTOS AGROPECUÁRIOS, CONSIDERANDO REQUISITOS TÉCNICOS, OPERACIONAIS, DE CONSERVAÇÃO E QUALIDADE.', NULL);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('PSV', 'PRODUTO SUSTENTÁVEL', 'CERTIFICAÇÃO DESTINADA A PRODUTOS VEGETAIS PRODUZIDOS DE ACORDO COM REQUISITOS DE SUSTENTABILIDADE, BOAS PRÁTICAS PRODUTIVAS E RESPONSABILIDADE SOCIOAMBIENTAL.', NULL);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('HACCP', 'HACCP', 'CERTIFICAÇÃO BASEADA NA IDENTIFICAÇÃO, AVALIAÇÃO, PREVENÇÃO E CONTROLE DE PERIGOS RELACIONADOS À SEGURANÇA DOS ALIMENTOS POR MEIO DE PONTOS CRÍTICOS DE CONTROLE.', NULL);
INSERT INTO CERTIFICACOES (CERTIFICACAO_SIGLA, CERTIFICACAO_NOME, DESCRICAO, ID_PROGRAMA) VALUES ('INS-ORG', 'INSUMOS PARA PRODUÇÃO ORGÂNICA', 'CERTIFICAÇÃO DESTINADA À AVALIAÇÃO DE INSUMOS UTILIZADOS NA PRODUÇÃO ORGÂNICA QUANTO AO ATENDIMENTO DOS REQUISITOS E NORMAS APLICÁVEIS.', (SELECT ID_PROGRAMA FROM CERTIFICACAO_PROGRAMAS WHERE PROGRAMA_SIGLA = 'SISORG'));
