INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('CAPACITACAO', 'ATIVIDADE VOLTADA AO DESENVOLVIMENTO OU APRIMORAMENTO DE CONHECIMENTOS E HABILIDADES.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('PALESTRA', 'APRESENTAÇÃO ORAL DESTINADA À TRANSMISSÃO DE INFORMAÇÕES, CONHECIMENTOS OU EXPERIÊNCIAS SOBRE DETERMINADO TEMA.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('DIA DE CAMPO', 'ATIVIDADE PRÁTICA REALIZADA EM CAMPO PARA DEMONSTRAÇÃO E TROCA DE CONHECIMENTOS SOBRE TÉCNICAS E PRÁTICAS PRODUTIVAS.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('OFICINA', 'ATIVIDADE PRÁTICA E PARTICIPATIVA DESTINADA AO APRENDIZADO E À APLICAÇÃO DE TÉCNICAS OU CONHECIMENTOS.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('TREINAMENTO', 'ATIVIDADE DE PREPARAÇÃO PRÁTICA E ORIENTADA PARA DESENVOLVIMENTO DE COMPETÊNCIAS ESPECÍFICAS.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('WORKSHOP', 'ATIVIDADE INTERATIVA DE APRENDIZADO, DISCUSSÃO E PRÁTICA SOBRE UM TEMA ESPECÍFICO.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('SEMINARIO', 'EVENTO DESTINADO À APRESENTAÇÃO, DISCUSSÃO E APROFUNDAMENTO DE TEMAS ESPECÍFICOS.');
INSERT INTO QUALIFICACOES_TIPOS (TIPO, DESCRICAO) VALUES ('VISITA TECNICA', 'ATIVIDADE REALIZADA EM PROPRIEDADES, EMPREENDIMENTOS OU INSTITUIÇÕES PARA OBSERVAÇÃO E APRENDIZADO DE PRÁTICAS E PROCESSOS.');
