INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('AGROINDÚSTRIA FAMILIAR', 'UNIDADE DE PEQUENA ESCALA VINCULADA À PRODUÇÃO FAMILIAR, DESTINADA AO BENEFICIAMENTO OU TRANSFORMAÇÃO DE PRODUTOS AGROPECUÁRIOS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'GASTRONOMIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ÁREA DE PRESERVAÇÃO', 'ESPAÇO DESTINADO PRIORITARIAMENTE À PROTEÇÃO E CONSERVAÇÃO DA VEGETAÇÃO, BIODIVERSIDADE, RECURSOS HÍDRICOS OU OUTROS ELEMENTOS AMBIENTAIS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SUSTENTABILIDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ÁREA DE RECUPERAÇÃO AMBIENTAL', 'ÁREA SUBMETIDA A AÇÕES DESTINADAS À RESTAURAÇÃO DE AMBIENTES DEGRADADOS E À RECUPERAÇÃO DE SUAS FUNÇÕES ECOLÓGICAS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SUSTENTABILIDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ARMAZÉM RURAL', 'ESTRUTURA DESTINADA AO ARMAZENAMENTO DE PRODUTOS AGRÍCOLAS, INSUMOS, EQUIPAMENTOS OU MATERIAIS RELACIONADOS À PRODUÇÃO RURAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'INFRAESTRUTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ASSENTAMENTO RURAL', 'ÁREA ORGANIZADA EM UNIDADES PRODUTIVAS DESTINADAS À INSTALAÇÃO E DESENVOLVIMENTO DE FAMÍLIAS BENEFICIÁRIAS DE PROGRAMAS DE REFORMA OU ORGANIZAÇÃO FUNDIÁRIA.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PROPRIEDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ATRATIVO ECOLÓGICO', 'LOCAL DE INTERESSE TURÍSTICO CUJA PRINCIPAL CARACTERÍSTICA ESTÁ RELACIONADA À NATUREZA, PAISAGEM, BIODIVERSIDADE OU CONSERVAÇÃO AMBIENTAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ATRATIVO RURAL', 'LOCAL SITUADO OU RELACIONADO AO MEIO RURAL QUE POSSUI CARACTERÍSTICAS CAPAZES DE DESPERTAR INTERESSE PARA VISITAÇÃO E EXPERIÊNCIAS TURÍSTICAS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRAL DE ABASTECIMENTO', 'ESTRUTURA DESTINADA À CONCENTRAÇÃO, ORGANIZAÇÃO E CIRCULAÇÃO DE PRODUTOS AGRÍCOLAS PARA ABASTECIMENTO DE MERCADOS E CONSUMIDORES.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'INFRAESTRUTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE ASSISTÊNCIA TÉCNICA', 'UNIDADE DESTINADA À PRESTAÇÃO DE ORIENTAÇÃO E SUPORTE TÉCNICO AOS PRODUTORES EM QUESTÕES RELACIONADAS À PRODUÇÃO, MANEJO E GESTÃO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SERVIÇOS'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE CAPACITAÇÃO', 'ESPAÇO DESTINADO À REALIZAÇÃO DE CURSOS, TREINAMENTOS E AÇÕES DE DESENVOLVIMENTO TÉCNICO OU PROFISSIONAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'EDUCAÇÃO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE COMPOSTAGEM', 'ESTRUTURA DESTINADA AO RECEBIMENTO E TRANSFORMAÇÃO CONTROLADA DE RESÍDUOS ORGÂNICOS EM COMPOSTO APROVEITÁVEL COMO CONDICIONADOR OU FERTILIZANTE DO SOLO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SUSTENTABILIDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE DISTRIBUIÇÃO', 'INSTALAÇÃO DESTINADA AO RECEBIMENTO, ORGANIZAÇÃO, ARMAZENAMENTO TEMPORÁRIO E DISTRIBUIÇÃO DE PRODUTOS PARA DIFERENTES DESTINOS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'INFRAESTRUTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE EDUCAÇÃO AMBIENTAL', 'ESPAÇO VOLTADO À FORMAÇÃO, CONSCIENTIZAÇÃO E DIVULGAÇÃO DE CONHECIMENTOS RELACIONADOS AO MEIO AMBIENTE E À SUSTENTABILIDADE.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'EDUCAÇÃO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE FORMAÇÃO RURAL', 'UNIDADE DESTINADA À FORMAÇÃO E APERFEIÇOAMENTO DE PRODUTORES, TRABALHADORES E DEMAIS PARTICIPANTES LIGADOS AO MEIO RURAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'EDUCAÇÃO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CENTRO DE PESQUISA AGRÍCOLA', 'INSTITUIÇÃO OU UNIDADE DESTINADA AO DESENVOLVIMENTO DE PESQUISAS, ESTUDOS E TECNOLOGIAS RELACIONADAS À AGRICULTURA E À PRODUÇÃO RURAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PESQUISA E TECNOLOGIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('CHÁCARA', 'PROPRIEDADE DE PEQUENO OU MÉDIO PORTE, GERALMENTE LOCALIZADA EM ÁREA RURAL OU PERIURBANA E UTILIZADA PARA PRODUÇÃO, RESIDÊNCIA OU LAZER.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PROPRIEDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('COZINHA COMUNITÁRIA', 'ESTRUTURA COLETIVA DESTINADA À PREPARAÇÃO DE ALIMENTOS PARA ATENDIMENTO COMUNITÁRIO, PROJETOS SOCIAIS OU PRODUÇÃO COMPARTILHADA.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'GASTRONOMIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('EMPÓRIO RURAL', 'ESTABELECIMENTO COMERCIAL ESPECIALIZADO EM PRODUTOS RURAIS, ARTESANAIS, AGRÍCOLAS OU PRODUZIDOS REGIONALMENTE.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ESCOLA AGRÍCOLA', 'INSTITUIÇÃO DE ENSINO COM FORMAÇÃO VOLTADA ÀS CIÊNCIAS AGRÁRIAS, PRODUÇÃO AGROPECUÁRIA E ATIVIDADES RELACIONADAS AO MEIO RURAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'EDUCAÇÃO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FAZENDA', 'PROPRIEDADE RURAL GERALMENTE DE MAIOR EXTENSÃO, UTILIZADA PARA ATIVIDADES AGRÍCOLAS, PECUÁRIAS, FLORESTAIS OU OUTRAS FORMAS DE PRODUÇÃO RURAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PROPRIEDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA DO PRODUTOR', 'ESPAÇO PERIÓDICO DE COMERCIALIZAÇÃO CARACTERIZADO PRINCIPALMENTE PELA VENDA DIRETA DE PRODUTOS REALIZADA PELOS PRÓPRIOS PRODUTORES.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA LIVRE', 'ESPAÇO DE COMÉRCIO PERIÓDICO ONDE DIFERENTES VENDEDORES COMERCIALIZAM ALIMENTOS, PRODUTOS AGRÍCOLAS E OUTROS GÊNEROS DIRETAMENTE AO PÚBLICO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('HORTA COMUNITÁRIA', 'ESPAÇO DE CULTIVO ADMINISTRADO OU UTILIZADO COLETIVAMENTE POR MORADORES, GRUPOS OU COMUNIDADES PARA PRODUÇÃO AGRÍCOLA E INTEGRAÇÃO SOCIAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'AGRICULTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('HORTA ESCOLAR', 'ESPAÇO DE CULTIVO LOCALIZADO OU VINCULADO A UMA INSTITUIÇÃO DE ENSINO, GERALMENTE UTILIZADO TAMBÉM COMO RECURSO PEDAGÓGICO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'AGRICULTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('HORTA INSTITUCIONAL', 'HORTA MANTIDA POR INSTITUIÇÃO PÚBLICA, PRIVADA OU ORGANIZAÇÃO PARA PRODUÇÃO, EDUCAÇÃO, ALIMENTAÇÃO OU OUTRAS FINALIDADES INSTITUCIONAIS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'AGRICULTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('JARDIM DE POLINIZADORES', 'ESPAÇO PLANEJADO COM ESPÉCIES VEGETAIS QUE OFERECEM ALIMENTO E ABRIGO PARA ABELHAS, BORBOLETAS E OUTROS ORGANISMOS POLINIZADORES.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SUSTENTABILIDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LOJA DE PRODUTOS LOCAIS', 'ESTABELECIMENTO ESPECIALIZADO NA COMERCIALIZAÇÃO DE PRODUTOS PRODUZIDOS OU ORIGINADOS PREDOMINANTEMENTE NA REGIÃO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('MERCADO DO PRODUTOR', 'ESPAÇO COMERCIAL ESTRUTURADO PARA CONCENTRAR E FACILITAR A VENDA DIRETA OU ORGANIZADA DA PRODUÇÃO DE AGRICULTORES E PRODUTORES LOCAIS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('MERCADO MUNICIPAL', 'ESTABELECIMENTO COMERCIAL PÚBLICO OU DE INTERESSE MUNICIPAL QUE REÚNE DIFERENTES COMERCIANTES E PRODUTOS DESTINADOS AO ABASTECIMENTO DA POPULAÇÃO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'COMÉRCIO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('POMAR URBANO', 'ÁREA LOCALIZADA EM AMBIENTE URBANO OU PERIURBANO DESTINADA PREDOMINANTEMENTE AO CULTIVO DE ÁRVORES E OUTRAS ESPÉCIES FRUTÍFERAS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'AGRICULTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('POUSADA RURAL', 'ESTABELECIMENTO DE HOSPEDAGEM LOCALIZADO EM AMBIENTE RURAL OU INTEGRADO A UMA PROPRIEDADE RURAL E ÀS CARACTERÍSTICAS LOCAIS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('PROPRIEDADE FAMILIAR', 'UNIDADE RURAL CUJA GESTÃO E ATIVIDADES PRODUTIVAS SÃO REALIZADAS PREDOMINANTEMENTE PELO PRODUTOR E SUA FAMÍLIA.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PROPRIEDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('RESTAURANTE RURAL', 'ESTABELECIMENTO GASTRONÔMICO LOCALIZADO OU INTEGRADO AO AMBIENTE RURAL, GERALMENTE ASSOCIADO À CULINÁRIA E AOS PRODUTOS DA REGIÃO.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'GASTRONOMIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ROTEIRO RURAL', 'CONJUNTO ORGANIZADO DE PROPRIEDADES, ATRATIVOS OU ESTABELECIMENTOS RURAIS INTEGRADOS EM UM PERCURSO DESTINADO À VISITAÇÃO TURÍSTICA.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'TURISMO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('SÍTIO', 'PROPRIEDADE RURAL DE PEQUENO OU MÉDIO PORTE DESTINADA À PRODUÇÃO AGRÍCOLA, CRIAÇÃO, RESIDÊNCIA, TURISMO OU COMBINAÇÃO DESSAS FINALIDADES.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PROPRIEDADE'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('UNIDADE DE APOIO AO PRODUTOR', 'ESTRUTURA QUE CONCENTRA SERVIÇOS, INFORMAÇÕES OU RECURSOS DESTINADOS A AUXILIAR PRODUTORES EM SUAS ATIVIDADES PRODUTIVAS E ADMINISTRATIVAS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SERVIÇOS'));
