INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('UNIDADE DE EXTENSÃO RURAL', 'UNIDADE DESTINADA À APROXIMAÇÃO ENTRE CONHECIMENTO TÉCNICO E PRODUTORES, OFERECENDO ORIENTAÇÃO, ACOMPANHAMENTO E DISSEMINAÇÃO DE PRÁTICAS AGRÍCOLAS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'SERVIÇOS'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('UNIDADE DEMONSTRATIVA', 'ESPAÇO UTILIZADO PARA APRESENTAR, AVALIAR E DIVULGAR TÉCNICAS, PRÁTICAS, TECNOLOGIAS OU MODELOS PRODUTIVOS APLICÁVEIS À AGRICULTURA.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PESQUISA E TECNOLOGIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('UNIDADE EXPERIMENTAL', 'ÁREA OU INSTALAÇÃO DESTINADA À REALIZAÇÃO CONTROLADA DE TESTES, EXPERIMENTOS E AVALIAÇÕES RELACIONADOS À PRODUÇÃO AGRÍCOLA OU AMBIENTAL.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'PESQUISA E TECNOLOGIA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('UNIDADE PEDAGÓGICA', 'ESPAÇO ESTRUTURADO PARA REALIZAÇÃO DE ATIVIDADES DE ENSINO, APRENDIZAGEM E DEMONSTRAÇÃO PRÁTICA DE CONHECIMENTOS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'EDUCAÇÃO'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('VIVEIRO', 'ESTRUTURA DESTINADA À PRODUÇÃO, DESENVOLVIMENTO, CONSERVAÇÃO OU DISTRIBUIÇÃO DE MUDAS DE ESPÉCIES AGRÍCOLAS, ORNAMENTAIS OU FLORESTAIS.', (SELECT ID_CATEGORIA FROM CATEGORIAS WHERE CATEGORIA = 'AGRICULTURA'));
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA ORGÂNICA', 'FEIRA DESTINADA À COMERCIALIZAÇÃO DE PRODUTOS ORGÂNICOS CERTIFICADOS OU PROVENIENTES DE SISTEMAS DE PRODUÇÃO ORGÂNICA.', 2);
