INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA DE FLORES E PLANTAS', 'FEIRA VOLTADA À COMERCIALIZAÇÃO DE FLORES, MUDAS, PLANTAS ORNAMENTAIS, ERVAS, SEMENTES E PRODUTOS RELACIONADOS À JARDINAGEM.', 2);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA DE PRODUTOS REGIONAIS', 'FEIRA DESTINADA À COMERCIALIZAÇÃO E VALORIZAÇÃO DE PRODUTOS CARACTERÍSTICOS DA PRODUÇÃO, CULTURA E GASTRONOMIA REGIONAL.', 2);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('FEIRA DE TROCA DE SEMENTES E MUDAS', 'FEIRA OU ENCONTRO DESTINADO À TROCA, DISTRIBUIÇÃO E CIRCULAÇÃO DE SEMENTES, MUDAS E MATERIAIS DE PROPAGAÇÃO ENTRE PRODUTORES E COMUNIDADES.', 2);
