INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LOJA DE MÁQUINAS E IMPLEMENTOS AGRÍCOLAS', 'ESTABELECIMENTO DESTINADO À COMERCIALIZAÇÃO DE TRATORES, MOTOCULTORES, IMPLEMENTOS, MÁQUINAS E EQUIPAMENTOS UTILIZADOS NAS ATIVIDADES AGRÍCOLAS.', 2);
