INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LOJA DE EQUIPAMENTOS DE IRRIGAÇÃO', 'ESTABELECIMENTO ESPECIALIZADO NA COMERCIALIZAÇÃO DE BOMBAS, TUBULAÇÕES, ASPERSORES, GOTEJADORES, CONTROLADORES E OUTROS EQUIPAMENTOS PARA SISTEMAS DE IRRIGAÇÃO.', 2);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LOJA DE FERTILIZANTES E ADUBOS', 'ESTABELECIMENTO COMERCIAL ESPECIALIZADO NA VENDA DE FERTILIZANTES MINERAIS, ADUBOS ORGÂNICOS, CORRETIVOS DE SOLO E PRODUTOS DESTINADOS À NUTRIÇÃO VEGETAL.', 2);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ESCRITÓRIO DE CONSULTORIA AGRONÔMICA', 'ESTABELECIMENTO PROFISSIONAL DESTINADO À PRESTAÇÃO DE CONSULTORIA AGRONÔMICA, ASSISTÊNCIA TÉCNICA, PLANEJAMENTO PRODUTIVO E ELABORAÇÃO DE PROJETOS AGRÍCOLAS.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('OFICINA DE MÁQUINAS AGRÍCOLAS', 'ESTABELECIMENTO ESPECIALIZADO NA MANUTENÇÃO PREVENTIVA E CORRETIVA, REVISÃO E REPARAÇÃO DE MÁQUINAS, IMPLEMENTOS E EQUIPAMENTOS AGRÍCOLAS.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LOCADORA DE MÁQUINAS AGRÍCOLAS', 'ESTABELECIMENTO DESTINADO À LOCAÇÃO DE TRATORES, MOTOCULTORES, ROÇADEIRAS, IMPLEMENTOS E OUTROS EQUIPAMENTOS UTILIZADOS NA PRODUÇÃO AGRÍCOLA.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('EMPRESA DE IRRIGAÇÃO AGRÍCOLA', 'ESTABELECIMENTO ESPECIALIZADO EM PROJETOS, INSTALAÇÃO, AUTOMAÇÃO E MANUTENÇÃO DE SISTEMAS DE IRRIGAÇÃO PARA HORTAS, LAVOURAS E PROPRIEDADES RURAIS.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('EMPRESA DE CONTROLE DE PRAGAS AGRÍCOLAS', 'ESTABELECIMENTO PRESTADOR DE SERVIÇOS DE MONITORAMENTO FITOSSANITÁRIO, MANEJO INTEGRADO DE PRAGAS E CONTROLE DE DOENÇAS QUE AFETAM CULTURAS AGRÍCOLAS.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('EMPRESA DE MECANIZAÇÃO AGRÍCOLA', 'ESTABELECIMENTO PRESTADOR DE SERVIÇOS MECANIZADOS DE PREPARAÇÃO DO SOLO, PLANTIO, ROÇAGEM, MANEJO DE CULTURAS E OPERAÇÃO DE MÁQUINAS AGRÍCOLAS.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('TRANSPORTADORA DE PRODUTOS AGRÍCOLAS', 'EMPRESA ESPECIALIZADA NO TRANSPORTE E NA LOGÍSTICA DE PRODUTOS AGRÍCOLAS, INSUMOS, MUDAS, EQUIPAMENTOS E MERCADORIAS RELACIONADAS À PRODUÇÃO RURAL.', 8);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('LABORATÓRIO DE ANÁLISE DE SOLO E ÁGUA', 'ESTABELECIMENTO TÉCNICO ESPECIALIZADO NA REALIZAÇÃO DE ANÁLISES FÍSICAS, QUÍMICAS E BIOLÓGICAS DE SOLO E ÁGUA, COM EMISSÃO DE LAUDOS PARA AVALIAÇÃO E MANEJO AGRÍCOLA.', 6);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('EMPRESA DE TECNOLOGIA AGRÍCOLA', 'ESTABELECIMENTO ESPECIALIZADO NO DESENVOLVIMENTO E FORNECIMENTO DE SOLUÇÕES TECNOLÓGICAS PARA AGRICULTURA, INCLUINDO SENSORIAMENTO REMOTO, AUTOMAÇÃO, MONITORAMENTO E AGRICULTURA DE PRECISÃO.', 6);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ESPAÇO DE VIVÊNCIA RURAL', 'LOCAL DESTINADO À REALIZAÇÃO DE EXPERIÊNCIAS PARTICIPATIVAS NO AMBIENTE RURAL, PERMITINDO AOS VISITANTES CONHECER A ROTINA DO CAMPO, PARTICIPAR DE ATIVIDADES AGRÍCOLAS E VIVENCIAR PRÁTICAS E TRADIÇÕES DA VIDA RURAL.', 10);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ESPAÇO DE EDUCAÇÃO AGROAMBIENTAL', 'LOCAL DESTINADO À REALIZAÇÃO DE ATIVIDADES EDUCATIVAS SOBRE AGRICULTURA, SUSTENTABILIDADE E PRESERVAÇÃO AMBIENTAL, INCLUINDO OFICINAS, VISITAS GUIADAS, EXPERIÊNCIAS PRÁTICAS DE CULTIVO E CONSCIENTIZAÇÃO ECOLÓGICA.', 3);
INSERT INTO SUBCATEGORIAS (SUBCATEGORIA, DESCRICAO, ID_CATEGORIA) VALUES ('ESPAÇO DE AGROTURISMO', 'ESTABELECIMENTO OU PROPRIEDADE RURAL DESTINADA À RECEPÇÃO DE VISITANTES PARA EXPERIÊNCIAS TURÍSTICAS RELACIONADAS À PRODUÇÃO AGRÍCOLA, INCLUINDO VISITAÇÃO, COLHEITA PARTICIPATIVA, DEGUSTAÇÃO DE PRODUTOS LOCAIS E VALORIZAÇÃO DA CULTURA RURAL.', 10);
